import type { FinancialImpactReport, FinancialBaseline, FullDiagnosisV2 } from './types';
/** Load FinancialBaseline for a team. Returns full baseline or undefined if not configured. */
export declare function loadFinancialBaseline(teamId: string): FinancialBaseline | undefined;
